from openpyxl import load_workbook

wb = load_workbook('sales_data.xlsx')
print("Sheets:", wb.sheetnames)
for name in wb.sheetnames:
    ws = wb[name]
    print(f"\n--- Sheet: {name} (dims: {ws.dimensions}, max_row={ws.max_row}, max_col={ws.max_column}) ---")
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 15)):
        for cell in row:
            if cell.value is not None:
                print(f"{cell.coordinate}: {cell.value!r}")

import importlib
for mod in ['pandas', 'openpyxl', 'xlrd']:
    try:
        m = importlib.import_module(mod)
        print(mod, "OK", getattr(m, '__version__', ''))
    except Exception as e:
        print(mod, "FAIL", e)

